# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
M=[['拉丁 mundus → mundanus','世界 → 属于现世的'],['古法语 mondain → 英语 mundane','世间的 → 日常、平凡的']]
P=[['拉丁 mappa“布” + mundi“世界的” → mappa mundi','世界地图；两个成分在短语中并列'],['古法语 mapemonde → 中古英语 mapemounde','世界地图'],['英语缩短为 map','地图；保留的是 mappa 部分，不是 mund- 变音']]
W=[
E('mundane','/mʌnˈdeɪn/','平凡的、日常而乏味的；世俗的〔较旧义〕','回到柴米油盐的日子，没有什么惊天动地的新鲜事。','接拉丁 mundanus“属于世界的”，经法语或拉丁语借入；mund- 是世界，不是 mind“头脑”。',M,'mundane tasks 是洗碗、填表、整理文件一类日常琐事。历史上先有“这个世界、现世的”，再转到普通日常生活，最后常带“不精彩、略乏味”的感觉。它并不表示这些事情没有价值，只是说它们缺乏新鲜感。','mundane tasks；mundane details；the mundane world。','ordinary 可以中性地说普通；mundane 常更突出平淡乏味。读音重在后面的 /deɪn/。',('The app helps with mundane tasks such as sorting receipts.','这个应用能帮忙处理整理收据这类日常琐事。'),('After the adventure, ordinary shopping felt strangely mundane.','经历那次冒险后，平常的购物竟显得格外平淡。'),sources=['https://www.etymonline.com/word/mundane','https://en.wiktionary.org/wiki/mundane']),
E('mundanity','/mʌnˈdænəti/','平淡乏味；日常琐事〔较书面〕','把生活里那些普通、重复、不起眼的部分合在一起看。','mundane + -ity，把性质变成名词；词形和读音随派生变化，重音所在元音由 /eɪ/ 变为 /æ/。',M+[['英语 mundane + -ity → mundanity','平淡这一性质；日常平凡之事']],'the mundanity of office life 是办公室生活的平淡；复数 mundanities 可以指购物、家务等一件件琐事。它既可表达厌倦，也可用于观察平凡生活中的细节，不一定全是贬义。','the mundanity of daily life；everyday mundanities；escape mundanity。','mundane 是形容词，mundanity 是名词。日常直接说 boring routines 通常更口语，mundanity 常见于评论或叙事。',('The film finds humour in the mundanity of daily life.','这部电影从日常生活的平淡中找到了幽默。'),('Travel offered a break from the usual mundanities.','旅行让人暂时摆脱了惯常的琐事。'),sources=['https://en.wiktionary.org/wiki/mundanity']),
E('map','/mæp/','地图；绘制地图；建立对应关系','把一个复杂空间或关系，整理成可找到位置的样子。','英语 map 与较长的“世界地图”一词缩短有关，源头短语是 mappa mundi。实际保留的 map 来自 mappa“布”，不是 mundus“世界”直接变成 map。',P,'地图把地点放到对应位置，后来 map 也用来把流程、区域或数据关系整理清楚。map out a plan 是把计划清晰铺开；程序和数学中的 map 可以表示把一组东西对应到另一组。它与 mund- 的联系在完整历史短语中，不能伪拆出一个隐藏的 mund。','a map of；read a map；map an area；map out a plan。','map 往往强调空间或对应关系；list 只是列项目，不一定显示项目怎样联系。',('The map shows a footpath along the river.','地图上标出了一条沿河步道。'),('We mapped out the main stages before starting the project.','开始项目之前，我们梳理出了主要阶段。'),sources=['https://www.etymonline.com/word/map','https://en.wiktionary.org/wiki/map']),
E('roadmap','英 /ˈrəʊdmæp/；美 /ˈroʊdmæp/','道路地图；行动路线与阶段计划','先看要去哪里，再看一路经过哪些步骤。','road + map 的英语合成词；借道路图的形象发展出计划义。map 与 mundus 的联系只在更早的 mappa mundi 短语中。',P+[['英语 road + map → roadmap','道路图 → 展示目标与步骤的计划']],'a product roadmap 描述产品接下来准备向哪些方向发展、先做什么后做什么；它通常是较高层的路线安排，不必细到每个人今天做哪一项任务。road map 分写也常见，这里按合写词收录。','a product roadmap；a roadmap for reform；develop a roadmap。','schedule 更强调日期与时间安排；roadmap 更强调方向、阶段和路径，两者可以同时存在。',('The team published a roadmap for the next six months.','团队公布了未来六个月的发展计划。'),('This chapter provides a roadmap for the rest of the book.','这一章为本书后续内容提供了阅读指引。'),sources=['https://en.wiktionary.org/wiki/roadmap']),
E('bitmap','/ˈbɪtmæp/','位图','把画面切成一格格像素，并记录各格的颜色信息。','英语 bit“二进制位”+ map“位置对应图”；信息单位与映射概念组成计算机术语，不是古典时期已有的完整词。',P+[['英语 bit + map → bitmap','用位表示的位置图 → 位图']],'把小图放得很大时，边缘可能显出一格格像素，这就是理解 bitmap 的直观入口。真实位图常用多位信息描述一个像素，不是所有位图都只有黑白两色；BMP 是一种文件格式，也不能和所有位图画等号。','a bitmap image；a bitmap font；convert to a bitmap。','vector graphics 用几何对象描述图形；bitmap 以像素阵列描述图像。普通照片很适合像素表示，两种形式各有用途。',('The icon is stored as a small bitmap image.','这个图标以小型位图保存。'),('Enlarging the bitmap made its jagged edges visible.','把位图放大后，它的锯齿边缘显露了出来。'),sources=['https://www.etymonline.com/word/bitmap','https://en.wiktionary.org/wiki/bitmap']),
E('mapper','英 /ˈmæpə/；美 /ˈmæpər/','制图者；建立映射的工具或程序','负责把位置或对应关系整理出来的人或工具。','map + -er；词尾辅音 p 双写，表示进行 map 这一动作的主体。',P+[['英语 map + -er → mapper','绘图或建立映射的人、工具']],'地理项目中的 mapper 可以是采集道路信息、参与制图的人。软件里的 mapper 可以把一种数据结构转换对应到另一种。先看它正在 map 什么，再决定译成制图者还是映射器，不能只背一个机械中文名。','a volunteer mapper；a data mapper；a mapper tool。','cartographer 专指地图制作方面的人；mapper 范围更宽，也可能是软件组件。',('Volunteer mappers added the missing footpaths.','志愿制图者补上了缺失的步道。'),('The data mapper connects each source field to a destination field.','这个数据映射工具把每个源字段对应到一个目标字段。'),sources=['https://en.wiktionary.org/wiki/mapper']),
E('mapping','/ˈmæpɪŋ/','绘图；映射；梳理对应关系','正在给东西找位置、连关系，把复杂情况看清楚。','map 双写 p 加 -ing；既可作动词形式，也可作过程或对应关系的名词。',P+[['英语 map + -ing → mapping','绘制地图的过程；建立或表示对应关系']],'mapping the coast 是测绘海岸，mapping customer needs 是梳理客户需求；a mapping between two sets 在数学里表示两组元素间的对应规则。这个词不是所有场景都在画一张看得见的纸质图。','mapping an area；a mapping between；data mapping；mapping out。','a map 是整理出来的图或对应表示，mapping 常强调过程，也可以直接指一项映射关系。',('The team is mapping the river before the survey begins.','团队正在正式调查开始前绘制河流地图。'),('We need a clear mapping between the old labels and the new ones.','我们需要明确旧标签和新标签之间的对应关系。'),sources=['https://en.wiktionary.org/wiki/mapping']),
E('mapped','/mæpt/','已绘制地图的；已对应、已梳理的','原来散落或未知的位置，现在已经标出来了。','map 双写 p 加 -ed；清辅音 p 后的 -ed 读 /t/，不是 /ɪd/。',P+[['英语 map → mapped','完成绘图；建立了对应关系']],'The area has been mapped 表示该区域已经完成地图测绘；字段 mapped to a column 表示被对应到某一列。mapped out 则常说计划或步骤已经梳理清楚，实际有没有执行还要看后文。','be mapped to；a mapped area；have everything mapped out。','mapped 是过去式或过去分词，mapping 是 -ing 形式；已经把路线列出来不等于已经走完路线。',('The caves had never been fully mapped before.','这些洞穴以前从未被完整测绘过。'),('Each category is mapped to a different colour.','每个类别都对应一种不同的颜色。'),sources=['https://en.wiktionary.org/wiki/mapped'])]
EX={w:'较冷门或局限领域的表达，按优先级暂略' for w in ['mondo','mondial','demimonde','antemundane','demimondaine','extramundane','intramundane','ultramundane','anima mundi']}
ROOT=dict(id='C0772',meaning='世界、现世；另讲世界地图短语的缩略后代',core='MUND = WORLD',image='从宏大的“世界”回到每天洗碗、填表的现世生活，就能理解 mundane 的平凡感。世界地图一支则保留了原短语里“布”的部分，不能当作 mund 的直接变音。',intro='拉丁 mundus 表世界，mundane 从属于现世发展为平凡日常。原表还收 map 及其派生，因为较长的世界地图名称源于 mappa mundi。不过缩短为 map 时，保留下的是 mappa；这一联系必须讲清，不能把同一个历史短语误当成同一词根直接派生。',forms='mund- 经法语可见 mond-，如 mondain；mundanity 是 mundane + -ity。mappa 与 mundi 在原短语里分别表示布与世界的：map 来源保留前一部分。roadmap、bitmap、mapper、mapping、mapped 都沿 map 继续发展。',branches=[['世界 → 日常平凡','mundane, mundanity'],['历史短语的缩略后代','map, roadmap, bitmap, mapper, mapping, mapped']],contrasts='mundane 的核心是平凡日常，map 的现代核心是空间与对应关系。二者的历史联系通过 mappa mundi 这整个短语，不存在 mundus 直接变成 map 的正常演变链。',practice='We mapped out a roadmap for automating mundane office tasks.\n\n我们梳理了一个计划，准备把日常琐碎的办公室任务自动化。',words=[w['word'] for w in W],exclude=EX)
if __name__=='__main__':
 for name,data in [('roots_mund',[ROOT]),('words_mund',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
